// AC1: the extension guide's two worked examples, one in TypeScript and one over JSON-RPC, build, pass conformance
// and run against the host; a method or slot the contract publishes with no guide entry, and a guide entry for a
// method the contract doesn't publish, each fail the drift test, naming it.
//
// The guide is docs/extension-guide.md, generated by scripts/guide.mjs from the published contract
// (extension-api.json) and its slot declarations (hub-slots.json); `--check` is its drift test, and `--api` and
// `--table` point it at copies of the contract, which is how the tests plant a method or a slot without editing
// the repo. The examples are docs/extension-guide/typescript and docs/extension-guide/json-rpc, each a package
// folder whose example.json declares the check it registers and the runs the guide shows (README, Readings: build,
// and what an example's run is). Neither example is in DeepBuild's signed release, so both run sandboxed, out of
// process, as a reader's own package would.
import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';
import { buildExample, exampleRun, GUIDE, LANES, openHost, openWorld, readApi, readTable, runGuideCheck, tempDir, ZERO, type ExampleName } from './helpers.ts';

/** Builds the example, then installs, checks, loads and runs it on a fresh host. */
async function buildsPassesAndRuns(name: ExampleName, code: 'index.ts' | 'main'): Promise<void> {
  const dir = await buildExample(name);
  expect(existsSync(join(dir, code)), `the ${name} example's code is its ${code}`).toBe(true);
  expect(existsSync(join(dir, code === 'main' ? 'index.ts' : 'main')), `the ${name} example has only its ${code}`).toBe(false);
  const run = exampleRun(dir);
  const manifest = JSON.parse(readFileSync(join(dir, 'deepbuild.json'), 'utf8')) as { id: string; checks?: string[] };
  expect(manifest.checks ?? [], `the ${name} example's manifest declares the check kind its example.json runs`).toContain(run.check);
  const outcomes = run.runs.map((r) => r.expect.outcome);
  expect(outcomes, `the ${name} example's runs show its check passing and failing, so a constant answer can't meet them`).toEqual(expect.arrayContaining(['passed', 'failed']));

  const h = await openHost(await openWorld());
  const p = await h.install({ from: dir, builtBy: null });
  const c = await h.check(p);
  expect(c, `the ${name} example passes conformance: ${JSON.stringify(c.reasons)}`).toMatchObject({ passed: true });
  const load = await h.load(p);
  expect(load, `the ${name} example loads, out of process in the sandbox: ${JSON.stringify(load)}`).toMatchObject({ status: 'loaded', place: 'sandbox' });
  expect(await h.checks(), `the ${name} example's check kind is in use`).toContainEqual({ kind: run.check, extension: manifest.id });
  for (const r of run.runs) {
    const result = await h.runCheck(run.check, r.spec, { checkout: tempDir('checkout'), deadline: 30_000 });
    expect(result, `the ${name} example's ${run.check} on ${JSON.stringify(r.spec)}`).toMatchObject(r.expect);
  }
}

describe('AC1 #351.1d3d1e53 the guide\'s two worked examples, in TypeScript and over JSON-RPC, build, pass conformance and run against the host; a published method or slot with no guide entry, and a guide entry for an unpublished method, each fail the drift test, naming it', () => {
  it('AC1 the TypeScript example builds, passes conformance and runs against the host', async () => {
    await buildsPassesAndRuns('typescript', 'index.ts');
  }, 120_000);

  it('AC1 the JSON-RPC example builds, passes conformance and runs against the host', async () => {
    await buildsPassesAndRuns('json-rpc', 'main');
  }, 120_000);

  it('AC1 the guide is generated from the published contract and names both examples; its drift test passes on the contract, and the preflight runs it', () => {
    expect(existsSync(GUIDE), `the extension guide is at ${GUIDE}`).toBe(true);
    const guide = readFileSync(GUIDE, 'utf8');
    for (const name of ['typescript', 'json-rpc']) expect(guide, `the guide names its ${name} example`).toContain(`extension-guide/${name}`);
    const r = runGuideCheck();
    expect(r.fails, `${r.stdout}\n${r.stderr}`).toEqual([]);
    expect(r.status, `${r.stdout}\n${r.stderr}`).toBe(0);
    expect(r.stdout, 'the drift test says PASS').toMatch(/^PASS guide/m);
    expect(readFileSync(LANES, 'utf8'), 'a lane of the local preflight runs the guide\'s drift test').toContain('scripts/guide.mjs');
  }, 300_000);

  it('AC1 a method the contract publishes with no guide entry fails the drift test, naming it', () => {
    const planted = {
      method: 'deep.frobnicate', variants: null, since: 'R2', stability: 'preview' as const, digest: ZERO,
      params: { type: 'object', properties: {}, required: [], additionalProperties: false },
    };
    const r = runGuideCheck({ api: [...readApi(), planted], table: readTable() });
    expect(r.status, `${r.stdout}\n${r.stderr}`).toBe(1);
    expect(r.fails.filter((line) => line.includes('deep.frobnicate')), `a FAIL guide line names deep.frobnicate: ${JSON.stringify(r.fails)}`).not.toEqual([]);
  }, 300_000);

  it('AC1 a slot the contract publishes with no guide entry fails the drift test, naming it', () => {
    const api = readApi().map((e) => (e.method === 'deep.registerSource' ? { ...e, variants: [...(e.variants ?? []), 'webhook'] } : e));
    const row = { method: 'deep.registerSource', variant: 'webhook', interface: 'webhook.source@1', digest: ZERO, fills: 'many', kit: null, planted: [], since: 'R2' };
    const r = runGuideCheck({ api, table: [...readTable(), row] });
    expect(r.status, `${r.stdout}\n${r.stderr}`).toBe(1);
    expect(r.fails.filter((line) => line.includes('webhook')), `a FAIL guide line names the slot deep.registerSource, webhook: ${JSON.stringify(r.fails)}`).not.toEqual([]);
  }, 300_000);

  it('AC1 a guide entry for a method the contract doesn\'t publish fails the drift test, naming it', () => {
    const published = readApi();
    expect(published.map((e) => e.method), 'the published contract has deep.notices.send, so the guide has an entry for it').toContain('deep.notices.send');
    const r = runGuideCheck({ api: published.filter((e) => e.method !== 'deep.notices.send'), table: readTable() });
    expect(r.status, `${r.stdout}\n${r.stderr}`).toBe(1);
    expect(r.fails.filter((line) => line.includes('deep.notices.send')), `a FAIL guide line names deep.notices.send: ${JSON.stringify(r.fails)}`).not.toEqual([]);
  }, 300_000);
});
